import {calculators} from './calculators.mjs';
export const NEW_KEY='ap-consulting-tools-extension-v1';
export const CRM_KEY='ap-consulting-crm-v1';
export const OLD_KEY='ap-consulting-tools-v1';
export const groups=['Sales & Client Acquisition','Consulting & Business Diagnostics','Financial & Business Management'];
export const category=id=>groups[['leads','scoring','crm','proposal'].includes(id)?0:['audit','savings','opportunities','profit','roi'].includes(id)?1:2];
export const stages=['New','Contacted','Responded','Discovery Scheduled','Discovery Completed','Proposal Sent','Negotiation','Won','Lost'];
export const qualification=[['severity','Financial problem severity',20],['budgetFit','Available budget',20],['urgency','Urgency',15],['access','Decision-maker access',15],['fit','Company fit',10],['readiness','Implementation readiness',10],['recurring','Recurring potential',10]];
export const auditCriteria={sales:[['crmRating','CRM usage and visibility',30],['followRating','Follow-up consistency',40],['salesRating','Sales measurement quality',30]],operations:[['scheduleRating','Scheduling efficiency',30],['entryRating','Duplicate entry avoidance',30],['loadRating','Workload and bottleneck management',40]],financial:[['marginRating','Margin visibility',40],['expenseRating','Expense visibility',35],['trackingRating','Financial tracking reliability',25]],ai:[['dataRating','Data quality',30],['integrationRating','Integration capability',25],['staffRating','Staff readiness',25],['privacyRating','Data safeguards',20]],growth:[['salesRating','Sales measurement quality',35],['loadRating','Workload and bottleneck management',35],['marginRating','Margin visibility',30]]};
export const n=x=>x===''||x===null||x===undefined?null:Number.isFinite(Number(x))?Number(x):null;
const z=x=>n(x)??0;
export const ratio=(a,b)=>b>0?a/b:null;
export function weighted(criteria,values,weights={}){let total=0,earned=0,answered=0;const breakdown=criteria.map(([key,label,weight])=>{if(Object.hasOwn(weights,key)&&n(weights[key])===null)throw Error('Every weight needs a number.');weight=n(weights[key])??weight;const value=n(values[key]);if(weight<0||weight>100||value!==null&&(value<0||value>100))throw Error('Scores and weights must be between 0 and 100.');total+=weight;if(value!==null){earned+=value*weight/100;answered+=weight}return {key,label,weight,value,points:value===null?null:value*weight/100}});if(Math.abs(total-100)>.00001)throw Error('Weights must total 100%.');return {score:answered?earned/(answered/100):null,coverage:answered,provisional:answered<100,breakdown};}
export function leadScore(v){const r=weighted(qualification,v,Object.fromEntries(qualification.map(([k,,w])=>[k,v['weight_'+k]??w])));const thresholds=[n(v.high)??80,n(v.qualified)??60,n(v.further)??40];if(thresholds.some(x=>x<0||x>100)||!(thresholds[0]>thresholds[1]&&thresholds[1]>thresholds[2]))throw Error('Thresholds must descend: high > qualified > further, within 0–100.');const s=r.score;r.label=s===null?'Unscored':s>=thresholds[0]?'High-priority prospect':s>=thresholds[1]?'Qualified prospect':s>=thresholds[2]?'Needs further qualification':'Low priority';r.next=s===null?'Gather qualification evidence.':s>=thresholds[0]?'Arrange a decision-maker discovery call.':s>=thresholds[1]?'Confirm budget, scope, and decision process.':s>=thresholds[2]?'Resolve missing qualification details.':'Use a low-touch follow-up after confirming fit.';r.service=z(v.severity)>=60?'ProfitOS Diagnostic':'Discovery / Business Launch Concierge';return r;}
export function savings(v){for(const [k,val] of Object.entries(v)){if(k!=='basis'&&n(val)!==null&&n(val)<0)throw Error('Savings inputs cannot be negative. Use larger recurring costs to model a loss.');}if(z(v.reduced)>z(v.hours))throw Error('Hours reduced cannot exceed weekly task hours per employee.');const hours=z(v.people)*z(v.reduced)*52/12,capacity=hours*z(v.rate);if(z(v.payroll)>capacity+.01)throw Error('Cash payroll reduction cannot exceed the recovered labor value.');if(z(v.unused)>z(v.subscriptions))throw Error('Removed subscription spending cannot exceed current subscription spending.');const op=['avoidable','errors','overtime','rework','waste'].reduce((a,k)=>a+z(v[k]),0);if(op>z(v.operating)+.01)throw Error('Non-overlapping operating cost reductions cannot exceed current monthly operating costs.');const gross=z(v.payroll)+z(v.unused)+op,recurring=z(v.replacement)+z(v.maintenance),net=gross-recurring,cost=z(v.implementation);return {hours,capacity,gross,recurring,net,annual:net*12,netAnnual:net*12-cost,payback:cost===0?0:ratio(cost,net),roi:ratio((net*12-cost)*100,cost),avoidance:z(v.avoidance),sensitivity:[50,75,100].map(p=>({p,net:gross*p/100-recurring,annual:(gross*p/100-recurring)*12-cost}))};}
export function opportunity(v){const values={repeat:v.repeat,rules:v.rules,data:v.data,compatibility:v.compatibility,ease:n(v.complexity)===null?null:100-n(v.complexity),safety:n(v.sensitivity)===null?null:100-n(v.sensitivity)};const r=weighted([['repeat','Repetitiveness',20],['rules','Rules-based suitability',20],['data','Data availability',20],['compatibility','Software compatibility',15],['ease','Implementation ease (100 − complexity)',15],['safety','Data safety (100 − sensitivity)',10]],values);const sensitive=n(v.sensitivity)===null||z(v.sensitivity)>=50||['Finance','Legal','Medical','People / HR'].includes(v.department);const h=z(v.frequency)*z(v.minutes)/60*z(v.people)*52/12;const hours=h*z(v.recovery)/100;return {...r,hours,capacity:hours*z(v.rate),sensitive,priority:sensitive?'Review safeguards before pilot':r.score===null?'Gather evidence':r.score>=75?'Prioritize a small pilot':r.score>=50?'Validate feasibility':'Improve the process first',method:sensitive?'Manual improvement with supervised assistance only':z(v.rules)>=75?'Traditional automation':z(v.data)>=60&&z(v.repeat)>=50?'AI assistance with human review':'Manual improvement',complexity:sensitive||z(v.complexity)>=60?'High':z(v.complexity)>=30?'Moderate':'Low',risks:[...(sensitive?['Sensitive decisions or data require specialist review and access controls.']:[]),'Estimated time recovery is capacity value, not guaranteed cash savings.','Validate error handling, data retention, and human review before use.']};}
export function audit(v){const scores=Object.entries(auditCriteria).map(([key,c])=>({key,...weighted(c,v,Object.fromEntries(c.map(([k,,w])=>[k,v['aw_'+key+'_'+k]??w])))}));const ranked=scores.filter(s=>s.score!==null).sort((a,b)=>a.score-b.score);const required=['leads','closing','targetClosing','transaction','contribution','cashSavings'];const complete=required.every(k=>n(v[k])!==null);const financial=complete?calculators.find(c=>c.id==='profit').calculate({l:n(v.leads),c:n(v.closing),t:n(v.targetClosing),v:n(v.transaction),m:n(v.contribution),s:n(v.cashSavings)}):null;return {scores,ranked,financial,provisional:scores.some(s=>s.provisional)||!v.company,engagement:ranked.length===0?'Mini discovery audit':ranked[0].key==='sales'?'Revenue Leakage Audit':ranked[0].key==='ai'?'ProfitOS Diagnostic before automation':'ProfitOS Diagnostic',strengths:scores.filter(s=>s.score>=70),weaknesses:scores.filter(s=>s.score!==null&&s.score<70)};}
export function crmStats(records,today=new Date().toISOString().slice(0,10)){const leads=records.filter(r=>!r.archived),open=leads.filter(r=>!['Won','Lost'].includes(r.stage));return {total:leads.length,active:open.length,upcoming:open.filter(r=>r.followup&&r.followup>=today).length,overdue:open.filter(r=>r.followup&&r.followup<today).length,proposals:open.filter(r=>r.stage==='Proposal Sent').length,won:leads.filter(r=>r.stage==='Won').length,pipeline:open.reduce((a,r)=>a+(n(r.value)??0),0)};}
const date=v=>!v||/^\d{4}-\d{2}-\d{2}$/.test(v)&&!Number.isNaN(Date.parse(v))&&new Date(v+'T00:00:00Z').toISOString().slice(0,10)===v;
export const leadText=['id','contact','business','email','phone','industry','website','source','service','stage','notes','added','contacted','followup'];
export function validateLead(record){if(!record||typeof record!=='object'||Array.isArray(record))throw Error('Each lead must be an object.');const out={};for(const k of leadText){let val=record[k]??'';if(typeof val!=='string'||val.length>10000)throw Error('Invalid or oversized lead field: '+k);out[k]=val;}if(!out.business.trim()&&!out.contact.trim())throw Error('A contact or business name is required.');if(!/^[a-zA-Z0-9_-]{1,100}$/.test(out.id))throw Error('Invalid lead ID.');if(!stages.includes(out.stage))throw Error('Unknown pipeline stage.');if(out.email&&!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(out.email))throw Error('Invalid email.');if(out.website){try{if(!['http:','https:'].includes(new URL(out.website).protocol))throw Error()}catch{throw Error('Website must use http:// or https://.')}}for(const k of ['added','contacted','followup'])if(!date(out[k]))throw Error('Invalid date: '+k);for(const k of ['value','score']){if(record[k]!=null&&typeof record[k]!=='number'&&typeof record[k]!=='string')throw Error('Invalid '+k);out[k]=n(record[k]);if(record[k]!==''&&record[k]!=null&&out[k]===null||out[k]!==null&&(out[k]<0||k==='score'&&out[k]>100))throw Error('Invalid '+k);}if(record.archived!==undefined&&typeof record.archived!=='boolean')throw Error('Invalid archive flag.');out.archived=record.archived??false;return out;}
export function parseCRM(raw){if(typeof raw!=='string'||raw.length>2000000)throw Error('Import limit is 2 MB.');let data;try{data=JSON.parse(raw)}catch{throw Error('Invalid JSON. No records changed.')}if(data?.version!==1||!Array.isArray(data.records)||data.records.length>1000)throw Error('Expected version 1 and up to 1,000 records.');const records=data.records.map(validateLead);if(new Set(records.map(r=>r.id)).size!==records.length)throw Error('Duplicate lead IDs.');return records;}
export function mergeLeads(current,incoming){const ids=new Set(current.map(r=>r.id));if(incoming.some(r=>ids.has(r.id)))throw Error('Import contains existing IDs. Export and use replace instead of merging.');if(current.length+incoming.length>1000)throw Error('Maximum 1,000 leads.');return [...current,...incoming];}
export const csv=(records)=>{const fields=[...leadText,'value','score','archived'];const cell=v=>'"'+String(v??'').replace(/^[\s]*[=+@-]/,m=>"'"+m).replaceAll('"','""')+'"';return [fields.join(','),...records.map(r=>fields.map(f=>cell(r[f])).join(','))].join('\r\n')};
export function makeRepository(storage){return {load(){const raw=storage.getItem(CRM_KEY);return raw?parseCRM(raw):[]},save(records){const validated=parseCRM(JSON.stringify({version:1,records}));storage.setItem(CRM_KEY,JSON.stringify({version:1,records:validated}));return validated},clear(){storage.removeItem(CRM_KEY)}};}
export function parseDraft(raw,known){if(typeof raw!=='string'||raw.length>2000000)throw Error('Import limit is 2 MB.');let d;try{d=JSON.parse(raw)}catch{throw Error('Invalid JSON.')}if(d?.version!==1||d.tool!==known||!d.values||typeof d.values!=='object'||Array.isArray(d.values))throw Error('This is not a version 1 draft for this tool.');return d.values;}
export function applyTransfer(current,patch){return {...current,...patch};}
